#!/usr/bin/env python3
"""Turn 35 Wave 82: WHY THE REFEREE DOMAIN STAYS THIN, AND WHAT HARD MODE ACTUALLY IS.

Wave 82's centrepieces:

1. THE REAL-WORLD-FOOTBALL CONTAMINATION, now documented. A search for DLS26 referee, card
   and penalty rules returns almost nothing but IFAB Laws of the Game, VAR protocols,
   Premier League guidance and MLS disciplinary codes. That is not a failed search - it is
   the finding. **DLS does not document its referee model anywhere on the open web, and any
   "rule" that reads like the Laws of the Game has been imported from real football.** This
   is recorded so no future wave mistakes IFAB material for DLS material.

2. WHAT HARD MODE ACTUALLY IS. The corpus had the official selector (Medium/Hard, introduced
   DLS25) and the community handicap perception. Wave 82 adds the positive characterisation
   nobody had written down: Hard is DLS *without* the randomness, and AI teams "play like
   actual teams to an extent" - plus the detail that the reported handicap intensifies in
   larger stadiums.

3. THE DLS26 SHOOTING REVERSAL. A first-month review reports that in DLS26 it is now easier
   to score in a 1v1 than from long range - the opposite of DLS25 - and that keepers are
   "even a bit too silly" in 1v1. Paired with the May 2026 update that improved GK AI
   specifically for 1v1s, that is a change that was made and then partly addressed.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w82')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

e_df=new_ev("A two-search sweep on DLS26 refereeing and on DLS26 weather/difficulty. The referee search returned ONLY real-world football law - IFAB Laws 5 and 12, the 2026/27 VAR protocol, Premier League VAR guidance, MLS and ASL disciplinary codes, and Bundesliga/DFB suspension rules - with no DLS-specific refereeing material at all. The weather/difficulty search returned: eslamgaming (FLAGGED - the rain/snow/fog traction and dynamic-weather claims), playdreamleaguesoccer.com (REJECTED six times - 'Rain affects ball speed, fog reduces visibility'), r/DreamLeagueSoccer 1h6gphe 'Gameplay Difficulty Added' (4 Dec 2024 - only Medium and Hard exist; 'hard mode is basically DLS without all the random and stupid gameplay... teams play like actual teams to an extent'), r/DreamLeagueSoccer 1pgj3fr 'DLS 26 is garbage' (7 Dec 2025 - the hard-mode handicap, the artificial ball-stealing, and the detail that the problems 'intensify in larger stadiums'), r/DreamLeagueSoccer 1pj67x3 'DLS 26 Community Review' (10 Dec 2025 - 'now it's easier to score in 1v1 than from long range, unlike in DLS25', 'goalkeepers are even a bit too silly in 1v1', and 'how ridiculously hard scenarios has become'), r/DreamLeagueSoccer 1ryf5wq (19 Mar 2026 - Cross Assist off, Kick Assist off, Auto Switch low, and 'NO auto switch is actually hard af to play on Live'), r/DreamLeagueSoccer hxzo5k (26 Jul 2020 - 'there are no difficulty settings in the game', superseded by the DLS25 selector), NamuWiki DLS2023 (5 Apr 2025 - four difficulties at easy/medium/hard/very hard paying 25/50/75/100 coins), sportsdunia best-settings table (3 Mar 2026) and dreamleaguesoccerkits.com best-settings (15 May 2026) - two third-party settings inventories, YouTube wish-list jyS1cOAeedI (9 Nov 2025 - requests fog, cloudy, light rain and VAR animations, which establishes those are absent), Google Play review (21 May 2026 - 'career mode is way too easy')",
    "THE REAL-WORLD-FOOTBALL CONTAMINATION, WHAT HARD MODE IS, THE DLS26 SHOOTING REVERSAL, AND THE SETTINGS INVENTORY. (1) THE CONTAMINATION, which is itself the finding: a search for DLS26 referee and card rules returns **only IFAB Laws of the Game, the 2026/27 VAR protocol, Premier League VAR guidance, MLS/ASL disciplinary codes and DFB suspension rules**. Not one DLS-specific refereeing source. So DLS does not document its referee model on the open web, and **any DLS 'rule' that reads like the Laws of the Game has been imported from real football and is not evidence.** The corpus's referee claims (five reds ends the match, five accumulated yellows = a one-match ban) therefore stand as the best available and must not be extended from football law. This is recorded as a methodology claim so no future wave repeats the search and mistakes IFAB material for DLS material. (2) WHAT HARD MODE IS, the positive characterisation the corpus lacked: '**Hard mode is basically DLS without all the random and stupid gameplay. In hard mode teams play like actual teams to an extent**' - and only two modes exist, Medium and Hard, since DLS25 removed Easy and Very Hard. A 2020 thread saying 'there are no difficulty settings in the game' is superseded by that selector. (3) THE HARD-MODE HANDICAP, with a new detail: 'The AI starts stealing balls artificially, while our players miss extremely simple passes, of a few meters. Throws gain an unrealistic force... All these bugs occur in both career mode and online, and **intensify in larger stadiums or when selecting the hard difficulty.**' The stadium-size coupling is new and worth testing, because it interacts with the corpus's stadium-capacity gate. (4) THE DLS26 SHOOTING REVERSAL: 'now it's easier to score in 1v1 than from long range, unlike in DLS25. It's still very easy to score from long range but at least now players are more inclined to try to get a big chance rather than just shoot. I have to admit that **goalkeepers are even a bit too silly in 1v1** tho.' Paired with the corpus's CLAIM-0549 (the May 2026 update improved GK AI specifically for 1v1 situations and corner handling), this is a change that was made and then partly addressed - so the December complaint may already be stale. (5) THE SCENARIO DIFFICULTY ROSE: 'Have you also noticed how ridiculously hard scenarios has become?' - a DLS26-specific observation on the mode that pays 50 coins a day, which changes its value as a daily routine. (6) THE ASSISTS POSITION, corroborated by a DLS26-dated voice (Mar 2026): 'Cross assist is horrible, everyone should turn it off if you want actual accurate crosses that don't just get collected by the enemy GK. Kick assist I turn off too. Auto switch I leave on low. It's annoying but **NO auto switch is actually hard af to play on Live**' - so Auto Switch is a genuine trade-off, not a free win. (7) THE SETTINGS INVENTORY, consolidated from two independent third-party settings guides: Gameplay (Language, Difficulty, Power Save, Camera Type, Camera Distance, Auto Replay, Quick Subs, Team Boosts, Multiplayer Chat), Controls (Virtual Stick Size, plus the assist toggles), Display (Graphics Quality, FPS, Crowd Detail, Shadows, Effects, Resolution, Battery Saver). Their competitive recommendations agree: Tele Broadcast camera, 60 FPS, Semi Auto switching, vibration off, commentary low or off, graphics medium. (8) A VERSION-HISTORY NOTE: DLS2023 carried four difficulties (easy/medium/hard/very hard) paying 25/50/75/100 coins, before DLS25 cut the list to Medium and Hard. (9) THE WISH-LIST CORROBORATION: a DLS26 wish-list asks for 'new weather conditions - fog, cloudy, light rain' and 'VAR animations (even if the decision is already made, show the review)', which independently confirms those are absent - and it means the eslamgaming and playdreamleaguesoccer weather-mechanic claims are contradicted by a source asking for the very conditions they describe.",
    "THE REAL-WORLD-FOOTBALL CONTAMINATION: a DLS referee search returns only IFAB law, VAR protocols and league disciplinary codes - DLS does not document its referee model, and any DLS rule that reads like the Laws of the Game has been imported from real football and is not evidence. WHAT HARD MODE IS: DLS without the randomness, with AI teams that 'play like actual teams to an extent'; only Medium and Hard exist since DLS25 cut Easy and Very Hard. THE HARD-MODE HANDICAP intensifies in larger stadiums as well as on Hard. THE DLS26 SHOOTING REVERSAL: 1v1 is now easier than long range, the opposite of DLS25, and keepers were 'too silly' in 1v1 - partly addressed by the May 2026 GK-AI update. SCENARIOS GOT HARDER in DLS26. THE ASSISTS POSITION corroborated: Cross Assist and Kick Assist off, Auto Switch low, and no-auto-switch is genuinely hard in Live. THE SETTINGS INVENTORY consolidated. DLS2023 had four difficulties paying 25/50/75/100 coins. A wish-list asking for fog, cloudy, light rain and VAR confirms those are absent",
    "THE REAL-FOOTBALL CONTAMINATION, WHAT HARD MODE IS, AND THE DLS26 SHOOTING REVERSAL",
    quality="community")

add_claim("METHODOLOGY FINDING - REAL-WORLD-FOOTBALL CONTAMINATION: a search for DLS26 referee, card and penalty rules returns **only** IFAB Laws 5 and 12, the 2026/27 VAR protocol, Premier League VAR guidance, MLS/ASL disciplinary codes and DFB suspension rules. Not one DLS-specific refereeing source. **DLS does not document its referee model on the open web, and any DLS 'rule' that reads like the Laws of the Game has been imported from real football and is not evidence.** Recorded so no future wave repeats the search and mistakes football law for game documentation.", 2, "errata/real-football-law-contamination", [e_df], notes="Explains why the referee domain stays thin; guards the corpus against imported rules")
add_claim("The corpus's referee claims therefore stand as the best available and must not be extended from football law: **five reds ends the match** and **five accumulated yellows = a one-match ban**. Everything else about DLS refereeing - card thresholds, penalty awards, DOGSO handling - is undocumented on the open web.", 3, "referee/corpus-position-stands", [e_df])
add_claim("WHAT HARD MODE IS, the positive characterisation the corpus lacked: '**Hard mode is basically DLS without all the random and stupid gameplay. In hard mode teams play like actual teams to an extent**' - and only two modes exist, Medium and Hard, since DLS25 removed Easy and Very Hard. A 2020 thread claiming 'there are no difficulty settings in the game' is superseded by that selector.", 3, "difficulty/what-hard-mode-is", [e_df])
add_claim("THE HARD-MODE HANDICAP, with a new detail: 'The AI starts stealing balls artificially, while our players miss extremely simple passes, of a few meters. Throws gain an unrealistic force... All these bugs occur in both career mode and online, and **intensify in larger stadiums or when selecting the hard difficulty.**' The stadium-size coupling is new and interacts with the corpus's capacity-gate rule - worth a deliberate test.", 3, "difficulty/handicap-intensifies-in-larger-stadiums", [e_df])
add_claim("THE DLS26 SHOOTING REVERSAL: 'now it's easier to score in 1v1 than from long range, unlike in DLS25. It's still very easy to score from long range but at least now players are more inclined to try to get a big chance rather than just shoot. I have to admit that **goalkeepers are even a bit too silly in 1v1** tho.' Paired with the May 2026 update that improved GK AI specifically for 1v1s (CLAIM-0549), this is a change that was made and then partly addressed - so the December complaint may already be stale.", 3, "shooting/dls26-1v1-easier-than-long-range", [e_df])
add_claim("THE SCENARIO DIFFICULTY ROSE IN DLS26: 'Have you also noticed how ridiculously hard scenarios has become?' A first-month observation on the mode that pays 50 coins a day against Hard AI - which changes its value as a daily routine if it now costs several attempts.", 3, "scenarios/difficulty-rose-in-dls26", [e_df])
add_claim("THE ASSISTS POSITION, corroborated by a DLS26-dated voice (Mar 2026): 'Cross assist is horrible, everyone should turn it off if you want actual accurate crosses that don't just get collected by the enemy GK. Kick assist I turn off too. Auto switch I leave on low. It's annoying but **NO auto switch is actually hard af to play on Live**.' So Auto Switch is a genuine trade-off rather than a free win, and the corpus's 'turn the assists off' advice now has a second source plus its cost.", 3, "controls/assists-off-with-the-cost", [e_df], notes="Second source for CLAIM-0431, and names the price of manual switching")
add_claim("THE SETTINGS INVENTORY, consolidated from two independent third-party settings guides. Gameplay: Language, Difficulty, Power Save, Camera Type, Camera Distance, Auto Replay, Quick Subs, Team Boosts, Multiplayer Chat. Controls: Virtual Stick Size plus the assist toggles. Display: Graphics Quality, FPS, Crowd Detail, Shadows, Effects, Resolution, Battery Saver. Their competitive recommendations agree - **Tele Broadcast camera, 60 FPS, Semi Auto switching, vibration off, commentary low or off, graphics medium**.", 3, "settings/consolidated-inventory", [e_df])
add_claim("VERSION-HISTORY NOTE: DLS2023 carried four difficulties - easy, medium, hard and very hard - paying 25/50/75/100 coins, before DLS25 cut the list to Medium and Hard. The only source giving per-difficulty coin figures; treat the amounts as DLS23-era.", 3, "difficulty/dls23-four-tiers-coin-scale", [e_df])
add_claim("THE WISH-LIST CORROBORATION: a DLS26 wish-list asks for 'new weather conditions - fog, cloudy, light rain' and 'VAR animations (even if the decision is already made, show the review)'. That independently confirms those are absent, and it means the weather-mechanic claims from the flagged and rejected sources describe conditions the community is still asking for.", 3, "weather/wishlist-confirms-absence", [e_df], notes="Corroborates CLAIM-410's wish-list finding from a second thread")
add_claim("A Google Play review (21 May 2026) reports 'career mode is way too easy and developers need to add extra difficulty to it' - which sits against the hard-mode handicap reports and the rising Scenario difficulty. **Difficulty sentiment in DLS26 is genuinely split by mode**, so the corpus should not carry a single difficulty verdict.", 4, "difficulty/sentiment-split-by-mode", [e_df])

for p in ['EV-495_real_football_contamination.html','EV-495b_hard_mode_and_shooting_reversal.html','EV-495c_settings_inventory.html']:
    with open(os.path.join(RAW_DIR,p),'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f'Added {cl_id-1-last_cl} claims (CLAIM-{last_cl+1:04d}..CLAIM-{cl_id-1:04d}) and 1 EV (EV-{last_ev+1:03d}). Totals: {n_cl} claims / {n_ev} EVs')
